<?php
session_start();require_once "../config/database.php";
if(!isset($_SESSION["user_id"])||$_SESSION["role"]!=="admin"){header("Location: ../auth/login.php");exit();}
$statuses=["Booked","Picked Up","In Transit","Out for Delivery","Delivered","Cancelled"];$message="";$error="";
if($_SERVER["REQUEST_METHOD"]==="POST"){$id=(int)($_POST["shipment_id"]??0);$status=$_POST["status"]??"";$loc=trim($_POST["location"]??"");if($id>0&&in_array($status,$statuses,true)){$q=$conn->prepare("UPDATE shipments SET status=? WHERE id=?");$q->bind_param("si",$status,$id);if($q->execute()){$q->close();$msg="Shipment status updated by admin.";$e=$conn->prepare("INSERT INTO shipment_events(shipment_id,status,location,message) VALUES(?,?,?,?)");$e->bind_param("isss",$id,$status,$loc,$msg);$e->execute();$e->close();$message="Shipment updated successfully.";}else{$error=$conn->error;$q->close();}}else{$error="Invalid shipment or status.";}}
$search=trim($_GET["search"]??"");$filter=trim($_GET["status"]??"");$sql="SELECT id,tracking_id,sender_name,receiver_name,origin,destination,status,priority,eta_hours FROM shipments WHERE 1=1";$params=[];$types="";
if($search!==""){$sql.=" AND (tracking_id LIKE ? OR sender_name LIKE ? OR receiver_name LIKE ? OR origin LIKE ? OR destination LIKE ?)";$v="%$search%";for($i=0;$i<5;$i++){$params[]=$v;$types.="s";}}
if($filter!==""&&in_array($filter,$statuses,true)){$sql.=" AND status=?";$params[]=$filter;$types.="s";}$sql.=" ORDER BY id DESC";$q=$conn->prepare($sql);if($params)$q->bind_param($types,...$params);$q->execute();$r=$q->get_result();
