*{box-sizing:border-box;font-family:Arial,sans-serif}body{margin:0;min-height:100vh;background:linear-gradient(135deg,#071e3d,#126e82,#1f8a70)}nav{background:#fff;padding:17px 5%;display:flex;justify-content:space-between}.logo{font-weight:bold;color:#073b4c}.nav a{margin-left:10px;text-decoration:none;color:#073b4c;font-weight:bold}.logout{background:#e63946;color:#fff!important;padding:8px;border-radius:8px}.container{width:95%;max-width:1400px;margin:35px auto}.title{color:#fff}.box{background:#fff;padding:20px;border-radius:18px;margin:20px 0;overflow:auto}.filters{display:flex;gap:10px}.filters input,.filters select{padding:12px;border:2px solid #ddd;border-radius:8px}.filters input{flex:1}.filters button{padding:12px 18px;border:0;border-radius:8px;background:#126e82;color:#fff;font-weight:bold}.success,.error{padding:12px;border-radius:8px;margin-bottom:15px}.success{background:#dcfce7;color:#166534}.error{background:#fee2e2;color:#b91c1c}table{width:100%;min-width:1200px;border-collapse:collapse}th{background:#073b4c;color:#fff;padding:12px;text-align:left}td{padding:12px;border-bottom:1px solid #eee}.id{color:#126e82;font-weight:bold}.update{background:#126e82;color:#fff;border:0;padding:9px;border-radius:7px;font-weight:bold}td form{display:flex;gap:5px}
</style></head><body><nav><div class="logo">🚚 Smart Logistics | Admin</div><div class="nav"><a href="dashboard.php">Dashboard</a><a href="shipments.php">Shipments</a><a class="logout" href="../auth/logout.php">Logout</a></div></nav><div class="container"><div class="title"><h1>📦 Manage Shipments</h1><p>Search, filter and update status.</p></div><div class="box"><?php if($message):?><div class="success"><?=htmlspecialchars($message)?></div><?php endif;?><?php if($error):?><div class="error"><?=htmlspecialchars($error)?></div><?php endif;?><form class="filters"><input name="search" value="<?=htmlspecialchars($search)?>" placeholder="Search tracking, sender, receiver or location"><select name="status"><option value="">All Statuses</option><?php foreach($statuses as $st):?><option <?=$filter===$st?"selected":""?>><?=htmlspecialchars($st)?></option><?php endforeach;?></select><button>🔎 Search</button></form></div><div class="box"><table><tr><th>Tracking</th><th>Sender</th><th>Receiver</th><th>Route</th><th>Priority</th><th>Status</th><th>ETA</th><th>Update</th></tr><?php while($x=$r->fetch_assoc()):?><tr><td class="id"><?=htmlspecialchars($x["tracking_id"])?></td><td><?=htmlspecialchars($x["sender_name"])?></td><td><?=htmlspecialchars($x["receiver_name"])?></td><td><?=htmlspecialchars($x["origin"])?> → <?=htmlspecialchars($x["destination"])?></td><td><?=htmlspecialchars($x["priority"])?></td><td><?=htmlspecialchars($x["status"])?></td><td><?=($x["eta_hours"]!==null&&$x["eta_hours"]!=="")?htmlspecialchars($x["eta_hours"])." hrs":"N/A"?></td><td><form method="POST"><input type="hidden" name="shipment_id" value="<?=$x["id"]?>"><select name="status"><?php foreach($statuses as $st):?><option <?=$x["status"]===$st?"selected":""?>><?=htmlspecialchars($st)?></option><?php endforeach;?></select><input name="location" placeholder="Location"><button class="update">Update</button></form></td></tr><?php endwhile;?></table></div></div></body></html><?php $q->close();$conn->close();?>